class _EditorState extends State<Editor> with SingleTickerProviderStateMixin {
  final _text = TextEditingController();
  final _scroll = ScrollController();
  final _focus = FocusNode();
  late final _anim = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 300),
  );

  StreamSubscription<Draft>? _sub;
  Timer? _autosave;

  @override
  void initState() {
    super.initState();                 // first
    _sub = widget.drafts.listen(_onDraft);
    _autosave = Timer.periodic(const Duration(seconds: 30), (_) => _save());
    _text.addListener(_markDirty);
  }

  @override
  void dispose() {
    _sub?.cancel();
    _autosave?.cancel();
    _text.removeListener(_markDirty);
    _text.dispose();
    _scroll.dispose();
    _focus.dispose();
    _anim.dispose();
    // widget.sharedController.dispose();  // ❌ not ours to dispose
    super.dispose();                   // last
  }

  @override
  Widget build(BuildContext context) => TextField(
        controller: _text,
        focusNode: _focus,
      );
}

