  setState(() async {                     // Future<void> Function() slips
    _user = await api.fetchUser();        // into a VoidCallback slot
  });                                     // dirty now, assigned much later
}

// ✅ await outside, setState with the result already in hand
Future<void> _load() async {
  setState(() => _loading = true);        // instant, synchronous
  try {
    final user = await api.fetchUser();
    if (!mounted) return;                 // the State may be gone by now
    setState(() => _user = user);         // one frame, one truth
  } finally {
    if (mounted) setState(() => _loading = false);
  }
}

