class _SaveButtonState extends State<SaveButton> {
  bool _saving = false;

  Future<void> _save() async {
    if (_saving) return;               // the second tap lands here
    setState(() => _saving = true);    // same synchronous slice — no race
    try {
      await widget.orders.submit(widget.cart);
      if (!mounted) return;
      Navigator.of(context).pop(true);
    } on ApiException catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text(e.message)));
    } finally {
      // ❌ resetting only after a success leaves a permanently dead button
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) => FilledButton(
        // the flag is the guard AND the affordance
        onPressed: _saving ? null : _save,
        child: _saving
            ? const SizedBox.square(
                dimension: 16,
                child: CircularProgressIndicator(strokeWidth: 2),
              )
            : const Text('Place order'),
      );
}

