// ✅ read what you don't own, sync what you do
class _EditorState extends State<Editor> {
  late final _text = TextEditingController(text: widget.body);
  StreamSubscription<Event>? _sub;

  @override
  void didUpdateWidget(covariant Editor oldWidget) {
    super.didUpdateWidget(oldWidget);          // super first
    if (widget.body != oldWidget.body) {
      _text.text = widget.body;                // guarded: not on every rebuild
    }
    if (widget.events != oldWidget.events) {
      _sub?.cancel();                          // old stream, old subscription
      _sub = widget.events.listen(_onEvent);
    }
  }

  @override
  Widget build(BuildContext context) => Column(children: [
        Text(widget.title),                    // no copy, no drift
        TextField(controller: _text),
      ]);
}

