class CartScope extends InheritedWidget {
  const CartScope({super.key, required this.items, required super.child});
  final List<Item> items;

  // ✅ registers this context as a dependent
  static CartScope of(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<CartScope>()!;

  // ❌ correct value once, then never a rebuild — no dependency registered
  static CartScope peek(BuildContext context) =>
      context.getInheritedWidgetOfExactType<CartScope>()!;

  @override
  bool updateShouldNotify(CartScope old) => old.items != items;
  //  ❌ `=> false` here silences every dependent in the subtree
}

