    if (!_formKey.currentState!.validate()) return;
    widget.onSend(_controller.text);
  }

  @override
  Widget build(BuildContext context) => Form(
        key: _formKey,
        autovalidateMode: AutovalidateMode.onUserInteraction,
        child: Column(children: [
          TextFormField(
            controller: _controller,      // never together with initialValue:
            validator: (v) =>
                (v == null || v.isEmpty) ? 'Say something' : null,
          ),
          ValueListenableBuilder<TextEditingValue>(
            valueListenable: _controller, // a ValueNotifier<TextEditingValue>
            builder: (context, value, _) => FilledButton(
              onPressed: value.text.isEmpty ? null : _send,
              child: Text('Send (${value.text.length})'),
            ),
          ),
        ]),
      );
}

