enum PrefAspect { currency, locale }

class Prefs extends InheritedModel<PrefAspect> {
  const Prefs({
    super.key,
    required this.currency,
    required this.locale,
    required super.child,
  });

  final String currency;
  final Locale locale;

  static String currencyOf(BuildContext context) =>
      InheritedModel.inheritFrom<Prefs>(context, aspect: PrefAspect.currency)!
          .currency;

  static Locale localeOf(BuildContext context) =>
      InheritedModel.inheritFrom<Prefs>(context, aspect: PrefAspect.locale)!
          .locale;

  // gate for the whole pass: false here and nobody is consulted
  @override
  bool updateShouldNotify(Prefs old) =>
      old.currency != currency || old.locale != locale;

  // asked once per dependent, with the aspects that dependent asked for
  @override
  bool updateShouldNotifyDependent(Prefs old, Set<PrefAspect> aspects) =>
      (aspects.contains(PrefAspect.currency) && old.currency != currency) ||
      (aspects.contains(PrefAspect.locale) && old.locale != locale);
}

