class _SurveyPageState extends State<SurveyPage> with RestorationMixin {
  final _step = RestorableInt(0);
  final _comment = RestorableTextEditingController();

  @override
  String? get restorationId => 'survey';

  @override
  void restoreState(RestorationBucket? oldBucket, bool initialRestore) {
    registerForRestoration(_step, 'step');
    registerForRestoration(_comment, 'comment');
  }

  @override
  void dispose() {
    _step.dispose();                 // restorable properties are ours to free
    _comment.dispose();
    super.dispose();
  }

  // reads and writes stay ordinary setState calls
  void _next() => setState(() => _step.value++);

  // routes restore too: static builder, serializable arguments
  static Route<void> _detailsRoute(BuildContext context, Object? id) =>
      MaterialPageRoute(builder: (_) => DetailsPage(id: id! as String));

  @override
  Widget build(BuildContext context) => Scaffold(
        body: ListView(
          restorationId: 'survey_scroll',   // the offset comes back too
          children: [
            Text('Step ${_step.value}'),
            TextField(controller: _comment.value),
            FilledButton(onPressed: _next, child: const Text('Next')),
            TextButton(
              onPressed: () => Navigator.restorablePush(
                  context, _detailsRoute, arguments: widget.itemId),
              child: const Text('Details'),
            ),
          ],
        ),
      );
}
